/* Vertiefung: eigenständige Beispiele statt weiterer Stichwortlisten. */
(() => {
 const add=(id,sections,q)=>{const l=COURSE.lessons.find(l=>l.id===id);l.sections.push(...sections);if(q)l.questions.push(q);};
 add('anforderungen',[
 S('Schritt für Schritt: aus „besserem Export“ wird eine Spezifikation','<p>Ein Kunde sagt: „Unsere Rechnungen sollen automatisch weiterverarbeitet werden“. Das benennt ein Problem, aber noch keine ausreichende Spezifikation. <b>1. Ziel klären:</b> Das Buchhaltungssystem soll die Rechnungen ohne erneute manuelle Erfassung übernehmen. <b>2. Systemgrenze:</b> Unsere Anwendung erzeugt die Datei; das fremde System importiert sie. Ein erfolgreicher Download beweist daher noch keinen erfolgreichen Import. <b>3. Vertrag festlegen:</b> Pflichtfelder, Datentypen, Währung, Encoding, Schema-Version und Fehlerbehandlung abstimmen. <b>4. Akzeptanz definieren:</b> Eine Rechnung mit zwei Positionen wird vom vereinbarten Testimporter akzeptiert; Netto, Steuer und Brutto stimmen überein. Eine fehlende Kundennummer erzeugt eine verständliche Fehlermeldung, keinen stillschweigenden unvollständigen Export.</p><p><b>Die Leistungsanforderung kommt separat hinzu:</b> etwa 100 Rechnungen innerhalb von 10 Sekunden unter angegebenen Testbedingungen. Zur Nachverfolgbarkeit kann jede Anforderung eine ID erhalten. Ein Test verweist auf diese ID, damit bei einer Änderung sichtbar wird, welche Prüfungen erneut nötig sind. Ein <b>Review</b> mit dem Kunden deckt widersprüchliche Erwartungen vor der Umsetzung auf.</p>','<p><b>الخطوة الأولى فهم الغرض:</b> تقليل الإدخال اليدوي، لا مجرد إضافة زر Export. ثم حدّد مسؤولية برنامجك ومسؤولية النظام الآخر. الاتفاق على أسماء الحقول ومعانيها ضروري؛ قد يكون السعر في نظام صافيًا وفي الآخر شاملًا للضريبة. بعد ذلك اكتب حالة نجاح وحالة فشل يمكن تجربتهما. تحديد ID لكل متطلب يربطه بالاختبار ويمنع نسيانه عند التعديل. لا تجعل <b>معيار القبول</b> «العميل راضٍ» فقط؛ الرضا مهم لكنه لا يوضح كيف نتحقق من كل وظيفة أو من جودة أدائها.</p>'),
 S('Typische Fehler und eine prüfungsfähige Antwort','<p>„Benutzerfreundlich“ ist ohne Nutzungskontext kaum messbar. „Wir verwenden Java“ ist zunächst eine Lösungs-/Technologievorgabe, keine fachliche Funktion. Und „Der Nutzer kann einen Export anfordern“ ist eine <b>User Story</b>, die noch Fehlerfälle und Rechte offenlässt. <b>Kurze Prüfungsantwort:</b> „Die Anwendung muss Rechnungen nach Schema X exportieren. <b>Akzeptanzkriterium</b>: Eine gültige Testrechnung wird verlustfrei importiert; bei fehlender Pflichtangabe wird der Export mit feldbezogenem Hinweis abgebrochen.“</p>','<p><b>في الامتحان لا يلزم كتابة دراسة كاملة لكل مطلب</b>. يكفي وصف وظيفة محددة وشرط قبول واضح إذا كان هذا المطلوب. لكن فهم المثال المفصّل يمكّنك من صياغة إجابة جديدة عندما تتغير الحالة، بدل تكرار عبارة محفوظة لا تناسب السؤال.</p>')
 ],Q('Ein Produktverantwortlicher fordert „keine Datenverluste“. Formuliere eine präzisere Betriebsanforderung und einen passenden Test.','Beispiel: Nach einem bestätigten Speichervorgang bleibt der Datensatz bei einem definierten Neustart erhalten. Test: Datensatz speichern, Bestätigung abwarten, Dienst kontrolliert neu starten und Inhalt/Version prüfen. Für Katastrophenfälle zusätzlich akzeptierten Datenverlust (RPO) und Wiederherstellung festlegen.','فرّق بين ثبات حفظ مؤكد وبين سيناريو طوارئ له شروط وحدود؛ عبارة مطلقة بلا سيناريو ليست اختبارًا واضحًا.'));
 add('methoden',[
 S('Ein konkretes Projekt: warum kurze Zyklen helfen','<p>Ein Portal soll Terminbuchungen anbieten. Der Kunde kann zu Beginn nicht entscheiden, ob freie Termine als Kalender oder Liste erscheinen sollen. Ein vollständiger Detailentwurf für sechs Monate würde diese Unsicherheit nur verdecken. Ein sinnvoller erster Schritt ist ein einfacher <b>Prototyp</b> beider Ansichten mit realistischen Aufgaben. Die gewonnenen Erkenntnisse fließen in ein priorisiertes <b>Product Backlog</b>. Im nächsten Sprint entwickelt das Team einen kleinen, vollständig getesteten Buchungsablauf statt gleichzeitig alle Masken halb fertigzustellen.</p><p>Im <b>Planning</b> vereinbart es ein überprüfbares <b>Sprint-Ziel</b>, etwa „Kunden können einen freien Termin verbindlich buchen“. Das <b>Sprint Backlog</b> beschreibt die dafür ausgewählte Arbeit und den Plan. Im Daily wird der Weg zu diesem Ziel geprüft, nicht lediglich der Führungskraft ein Statusbericht gegeben. Im <b>Review</b> probieren Stakeholder das Ergebnis aus; neue Wünsche verändern die weitere Priorisierung. In der <b>Retrospektive</b> fällt auf, dass zu späte API-Abstimmungen die Arbeit blockieren. Das Team vereinbart deshalb ein frühes Schnittstellenreview als konkrete Prozessverbesserung. Agilität funktioniert hier durch Rückkopplung und Qualitätsdisziplin.</p>','<p>الغموض في شكل التقويم لا يُحل بتخمين مبكر ثم الدفاع عنه. Prototype صغير يوفّر معرفة قبل صرف كلفة كبيرة. بعده نفّذ مسارًا مكتملًا، مثل حجز موعد مع التحقق من التوافر، بدل خمس واجهات لا تعمل معًا. فرق <b>Review</b> وRetrospektive يظهر في المثال: الأولى تراجع نتيجة المنتج، والثانية تعالج مشكلة التنسيق التي أخّرت الفريق. وإضافة قصة جديدة لا تعني أن كل العمل يتغير عشوائيًا أثناء Sprint؛ يجب الحفاظ على هدف واضح والتنسيق بشأن التغييرات.</p>'),
 S('Wann ein anderer Ansatz sinnvoller sein kann','<p>Bei einer exakt vorgeschriebenen, wenig veränderlichen Schnittstelle kann ein stärker vorausgeplanter Ansatz angemessen sein. Das <b>V-Modell</b> hilft, die Prüfungen zu jeder Spezifikationsstufe früh zu planen. Bei technischen Hochrisiken betont das <b>Spiralmodell</b> die Risikobearbeitung pro Zyklus. <b>Kanban</b> passt besonders zur kontinuierlich eintreffenden Arbeit: Ein <b>WIP-Limit</b> von drei Entwicklungsaufgaben zwingt das Team, zunächst begonnene Aufgaben fertigzustellen. <b>Prüfungsantwort:</b> Methode nennen, zwei fallbezogene Vorteile und eine Grenze erläutern.</p>','<p>لا يوجد نموذج يفوز دائمًا. إذا كانت المواصفات ثابتة والاعتمادات الرسمية مهمة، اشرح قيمة التخطيط المسبق. إذا كانت المهام تصل تباعًا في دعم وصيانة، افهم تدفق <b>Kanban</b> وحدوده. عبارة «Scrum أسرع» لا تبرّر وحدها أي قرار.</p>')
 ],Q('Ein Team nutzt ein Kanban-Board, aber startet bei jedem Hindernis eine neue Aufgabe. Welche konkrete Änderung hilft und warum?','WIP-Limit setzen und blockierte Arbeit sichtbar bearbeiten/escalieren. So begrenzt man parallele Arbeit, verringert Kontextwechsel und konzentriert sich auf den Abschluss statt auf immer neue Anfänge.','اللوحة وحدها لا تضبط التدفق؛ الحد على المهام الجارية هو جزء أساسي من الحل.'));
 add('planung-rechnen',[
 S('Netzplan vollständig gerechnet','<p>Wir betrachten A (2 Tage). Danach laufen B (4) und C (3) parallel; D (2) darf erst starten, wenn beide fertig sind. Startzeitpunkt ist 0. <b>Vorwärtsrechnung</b>: A 0–2; B 2–6; C 2–5; D beginnt bei max(6,5)=6 und endet bei 8. Rückwärts ab Projektende 8: D muss spätestens 6 starten. Deshalb müssen B und C spätestens bei 6 enden; B startet spätestens 2, C spätestens 3. A muss bis min(2,3)=2 beendet sein, also spätestens 0 starten.</p><table class="term-table"><tr><th>Vorgang</th><th>FAZ/FEZ</th><th>SAZ/SEZ</th><th>Gesamtpuffer</th></tr><tr><td>A</td><td>0 / 2</td><td>0 / 2</td><td>0</td></tr><tr><td>B</td><td>2 / 6</td><td>2 / 6</td><td>0</td></tr><tr><td>C</td><td>2 / 5</td><td>3 / 6</td><td>1</td></tr><tr><td>D</td><td>6 / 8</td><td>6 / 8</td><td>0</td></tr></table><p>A–B–D ist <b>kritisch</b>. Eine Verzögerung von C um einen Tag ist bei diesen Annahmen möglich, ohne das Projektende zu verschieben. Dauert B einen Tag länger, verschiebt sich hingegen der früheste Start von D und damit das Ende.</p>','<p><b>نفّذ الحساب مرتين باتجاهين مختلفين:</b> للأمام لمعرفة أبكر إنجاز، وللخلف لمعرفة آخر مواعيد لا تؤخر المشروع. عند التقاء السابقين نأخذ الأكبر، لأن D ينتظر كليهما. في العودة إلى مهمة لها عدة لاحقين نأخذ أصغر بداية متأخرة. C لديها يوم سماح واحد لأنها أقصر من B؛ لا تضف هذا اليوم إلى <b>المسار الحرج</b>. هذه الطريقة أوضح من تخمين المهام الحرجة بصريًا في شبكة كبيرة.</p>'),
 S('Risiken und Schätzungen an den Plan anbinden','<p>Wenn die externe API unklar ist, reicht ein pauschaler Terminpuffer nicht als Risikomaßnahme. Ein früher technischer Spike/<b>Prototyp</b> kann das Risiko vor abhängigen Arbeitspaketen reduzieren. Schätzung und tatsächliche Dauer vergleichen, Abweichungsursachen dokumentieren. Bei Drei-Punkt-Werten 2, 5 und 14 Tagen ergibt sich (2+4×5+14)/6 = 6 Tage; der pessimistische Wert bleibt trotzdem als Risiko relevant. Ein Erwartungswert beseitigt Unsicherheit nicht.</p>','<p><b>الجدول لا يضمن نجاح المشروع إذا كانت فرضياته خاطئة</b>. اربط خطر API بنشاط تحقق مبكر ومسؤول واضح، ثم عدّل التقدير وفق ما تعلّمته. Puffer يساعد الامتصاص، لكنه ليس بديلًا عن معالجة مصدر عدم اليقين.</p>')
 ],Q('Im Beispiel wird C um zwei Tage länger, sonst bleibt alles gleich. Neue Projektdauer?','C dauert dann 5 Tage und endet frühestens bei 7. D startet bei max(B-Ende 6,C-Ende 7)=7 und endet bei 9. Der bisherige Puffer von einem Tag reicht nur für einen Teil der Verlängerung.','أول يوم إضافي يستهلك السماح، والثاني يؤخر المشروع يومًا.'));
 add('wirtschaftlichkeit',[
 S('Make-or-buy mit vollständigen Kosten','<p>Eine <b>Eigenentwicklung</b> kostet einmalig 30.000 € und jährlich 6.000 € für Betrieb/Wartung. Ein <b>Standardprodukt</b> kostet einmalig 10.000 € und jährlich 14.000 € inklusive Lizenzen. Ohne Zinsen und Preisänderungen sind die Kosten nach t Jahren: <b>Eigenentwicklung</b> 30.000+6.000t, Kauf 10.000+14.000t. Gleichsetzen: 20.000=8.000t, also t=2,5 Jahre. Nach einem Jahr ist Kauf günstiger (24.000 statt 36.000 €); nach vier Jahren ist die <b>Eigenentwicklung</b> günstiger (54.000 statt 66.000 €). Der Nutzungszeitraum verändert die Entscheidung.</p><p>Dieser Kostenvergleich entscheidet noch nicht alles: Passt das Produkt zu Muss-Anforderungen? Ist eigenes Wartungspersonal vorhanden? Wie teuer sind Datenmigration und späterer Wechsel? Eine <b>Nutzwertanalyse</b> kann zusätzlich Sicherheit, Anpassbarkeit und Bedienung bewerten. Sie sollte den Kostenvergleich ergänzen, ihn nicht durch beliebige Punktzahlen unsichtbar machen. Lege offen, ob qualitative Kriterien und monetäre Kosten getrennt oder in einem transparenten Gesamtschema beurteilt werden.</p>','<p>الحل لا يبدأ باختيار الأرخص عند الشراء. اكتب كلفة البداية وكلفة كل سنة لكل بديل ثم قارن المدة نفسها. نقطة 2.5 سنة تعني تساوي الكلف التراكمية وفق الفرضيات؛ ليست تلقائيًا <b>Amortisation</b> من وفورات مشروع واحد. قد تختار شراءً أغلى لاحقًا إذا لم يوجد فريق صيانة أو لا تتحقق متطلبات إلزامية في التطوير الذاتي. القرار الجيد يبيّن الرقم وحدود النموذج والسبب العملي.</p>'),
 S('Nutzen in einer kurzen Empfehlung ausdrücken','<p><b>Eine prüfungsfähige Empfehlung lautet z. B.:</b> „Bei geplanter Nutzung von vier Jahren ist die <b>Eigenentwicklung</b> im Modell um 12.000 € günstiger. Sie ist zu empfehlen, wenn Wartungsressourcen und Muss-Anforderungen gesichert sind; das Personal-/Terminrisiko muss zusätzlich bewertet werden.“ Vermeide unklare Ausdrücke wie „lohnt sich mehr“ ohne Zeitraum und Kriterien. Bei <b>Amortisation</b> den jährlichen <b>Netto</b>-Rückfluss verwenden; bei TCO alle relevanten Kosten über denselben Zeitraum betrachten.</p>','<p><b>جملة التوصية قصيرة لكنها تسند القرار بدليلين:</b> فرق كلفة محدد وشرط واقعي. لا يلزم نسخ كل الشرح في الورقة، لكن يجب أن تستطيع الدفاع عن العلاقة بين الحساب والنتيجة.</p>')
 ],Q('Im Beispiel steigt die jährliche Eigenwartung auf 10.000 €. Wann gleichen sich die Kosten aus?','30.000+10.000t = 10.000+14.000t → 20.000=4.000t → t=5 Jahre. Höhere laufende Eigenkosten verschieben den Kostenvorteil nach hinten.','أعد بناء المعادلة؛ لا تغيّر النتيجة السابقة بنسبة عشوائية.'));
 add('kunden',[
 S('Ein Missverständnis fachlich auflösen','<p><b>Der Kunde sagt:</b> „Seit dem Update ist alles langsamer“. Eine vorschnelle technische Antwort wäre „Unsere CPU ist nicht ausgelastet“. Damit wurde das Kundenproblem noch nicht verstanden. Frage zunächst nach Tätigkeit, Zeitpunkt, Umfang und konkretem Beispiel: Betrifft es die Suche oder das Speichern? Alle Nutzer oder nur einen Standort? Seit welchem Datum? Beim aktiven Zuhören bestätigst du das erfasste Problem: „Das Speichern einer großen Rechnung dauert seit Montag etwa 15 statt 3 Sekunden; die Suche bleibt normal.“</p><p>Diese präzise Aussage führt zu einer reproduzierbaren Störungsmeldung. Erfasse Umgebung, Version, Testfall und Auswirkungen, ohne unnötige personenbezogene Daten zu sammeln. Vereinbare den nächsten Schritt und einen Rückmeldezeitpunkt, statt eine ungesicherte Lösung zu versprechen. Im <b>Vier-Seiten-Modell</b> kann „Das dauert ja ewig“ neben Sachinhalt auch einen Appell („Bitte helfen“) und Unzufriedenheit auf Beziehungsebene enthalten. Antworte sachlich und respektvoll, ohne Motive als gesicherte Tatsache zu unterstellen.</p>','<p>سؤال العميل قد يصف عرضًا عامًا بينما يحتاج الفريق حالة تقنية دقيقة. <b>إعادة الصياغة</b> تربط الطرفين: هل فهمنا المهمة والوقت والأثر؟ عدم استهلاك <b>CPU</b> ليس نفيًا لبطء بسبب شبكة أو قاعدة بيانات. عند جمع الأدلة لا تطلب ملف عملاء كاملًا إذا تكفي <b>بيانات اختبار</b>. وثّق من يفعل ماذا ومتى يعود للعميل؛ بذلك تتحول المحادثة إلى متابعة قابلة للتحقق.</p>'),
 S('Beispiel für eine brauchbare Dokumentationsstruktur','<p>Ein Benutzerhandbuch für Rechnungsimporte enthält: Ziel und unterstützte Dateiversion; benötigte Berechtigung; Vorbereitung; nummerierte Schritte; Beispiel einer gültigen Datei; erwartete Erfolgsmeldung; häufige Fehler mit Korrektur; Kontakt/Eskalation. Die Entwicklerdokumentation ergänzt Felddefinitionen und Fehlercodes, der Betriebsleitfaden <b>Backup</b> und Wiederanlauf. Ein Tortendiagramm für Anteile und ein Linienverlauf für Antwortzeiten beantworten unterschiedliche Fragen. Verwende Einheiten und keine abgeschnittenen Achsen, die Unterschiede irreführend vergrößern.</p>','<p>الوثيقة ليست مستودع كل ما يعرفه المطوّر. اختر ما يحتاجه القارئ لإنجاز مهمته. يهم المستخدم كيف يصحح <b>CSV</b> مرفوضًا؛ ويهم المشغّل كيف يعيد الخدمة؛ ويهم المطوّر ما الذي يعنيه حقل أو رمز خطأ.</p>')
 ],Q('Warum ist „Bitte senden Sie alle Kundendaten, damit wir suchen können“ oft keine angemessene erste Reaktion auf einen Fehler?','Zunächst reproduzierenden minimalen Testfall und notwendige technische Metadaten ermitteln. Das reduziert Datenschutzrisiken und Suchaufwand; reale Daten nur bei begründetem Bedarf, Berechtigung und geeignetem Schutz verarbeiten.','التصغير الدقيق للحالة يفيد التشخيص وحماية البيانات معًا.'));
 add('ux',[
 S('Ein Formular anhand einer Aufgabe entwerfen','<p><b>Aufgabe:</b> Eine Sachbearbeiterin soll einen Artikel zu einer Rechnung hinzufügen. Das Formular benötigt die Auswahl eines existierenden Artikels, Menge und eine klar berechnete Positionssumme. Zeige verfügbare Einheiten und Preisbasis an, statt die Nutzerin raten zu lassen. Ein geeignetes <b>Mock-up</b> beschreibt auch Zustände: anfänglich keine Auswahl; nach Auswahl Preis angezeigt; ungültige Menge markiert mit Text; nach erfolgreichem Speichern neuer Eintrag und verständliche Rückmeldung. Der Speichern-Button darf bei gesperrter Aktion nicht lediglich ohne Erklärung verschwinden.</p><p>Ein Test mit einer Person aus der <b>Zielgruppe</b> könnte lauten: „Füge drei Stück Artikel X hinzu und korrigiere danach auf zwei“. Beobachte <b>Erfolgsquote</b>, Zeit und Fehlversuche. Sage nicht jeden nötigen Klick vor, sonst testest du deine Anleitung statt die <b>Bedienbarkeit</b>. Bei Farben prüfen, ob der Status auch ohne Farberkennung verständlich ist. Labels bleiben sichtbar, auch wenn Werte eingetragen sind. Technisch sind <b>Tab-Reihenfolge</b>, <b>Fokus</b> und programmatische Fehlerzuordnung ebenso relevant wie Layout.</p>','<p><b>صمّم لسير مهمة فعلية</b>، لا لملء الشاشة بعناصر. المهم أن يعرف المستخدم أي منتج اختار، ووحدة الكمية، وما الذي سيحفظه الزر. «تم الحفظ» يجب أن يظهر أثرًا يمكن التحقق منه، لا مجرد حركة. في اختبار الاستخدام أعطِ هدفًا لا خطوات مفصلة؛ إذا وجهت الشخص عند كل تعثر فلن تكتشف ضعف التصميم. والاختبار بوظيفة صحيحة حسابيًا لا يكشف وحده مشكلة تسمية أو ترتيب أو إتاحة.</p>'),
 S('Begründungen, die in einer Prüfung tragen','<p><b>Schwach:</b> „Das Formular ist unübersichtlich“. Besser: „Artikelbezeichnung und Auswahl stehen weit auseinander; dadurch ist unklar, zu welchem Feld der Hinweis gehört. Label direkt zuordnen und zusammengehörige Felder gruppieren.“ Schwach: „Mehr Farben“. Besser: „Fehler zusätzlich als Text und mit Symbol kennzeichnen, damit Farbsinnstörungen die Information nicht verdecken.“ Gute Verbesserungsvorschläge nennen Beobachtung, Auswirkung und konkrete Änderung.</p>','<p><b>كل نقد يحتاج أثرًا على المستخدم وحلًا محددًا</b>. لا تستبدل الألوان عشوائيًا أو تضف نافذة لكل خطوة. الهدف تقليل الخطأ والجهد مع إبقاء المستخدم مسيطرًا على العمل.</p>')
 ],Q('Eine Fehlermeldung „Ungültige Eingabe“ erscheint oben; das falsche Feld ist weit unten. Nenne zwei konkrete Verbesserungen.','Betroffenes Feld mit verständlichem Fehlertext und Korrekturhinweis direkt verknüpfen; eine Fehlerzusammenfassung mit Navigation zum Feld und sinnvoller Fokusführung bereitstellen. Korrekte Eingaben erhalten.','المستخدم يجب أن يعرف أين الخطأ وكيف يصلحه دون إعادة كل البيانات.'));
 add('trends',[
 S('KI-Einführung als überprüfbaren Pilot planen','<p><b>Ein Team erwägt einen KI-Assistenten für Testentwürfe</b>. Die Ausgangslage wird gemessen: Wie lange dauern vergleichbare Aufgaben ohne Werkzeug und wie viele fachlich brauchbare Tests entstehen? Für einen Pilot werden nicht vertrauliche oder ausdrücklich freigegebene Beispiele genutzt. Das Team prüft, ob Vorschläge tatsächlich die Anforderungen abdecken, gültige Erwartungen besitzen und keine unnötigen personenbezogenen Daten an einen externen Dienst übertragen. Eine hohe Zahl generierter Tests ist noch kein Qualitätsgewinn.</p><p><b>Ein sinnvolles Ziel könnte sein:</b> Innerhalb von vier Wochen sinkt die mittlere Entwurfszeit vergleichbarer Tests um 20 %, bei unverändert bestandenen fachlichen Reviews und ohne unzulässige Datenübermittlung. Kosten für Lizenzen, <b>Review</b> und Nacharbeit einrechnen. Wenn ein Modell erfundene APIs nutzt, muss der Code gegen echte Dokumentation und Tests verifiziert werden. Ein <b>Rollback</b> zur bisherigen Arbeitsweise und klare Freigaberegeln halten das Experiment kontrollierbar. Die Entscheidung beruht anschließend auf beobachtetem Nutzen und Risiken, nicht auf der Begeisterung für ein neues Schlagwort.</p>','<p>حتى نقيس نجاح KI نحتاج <b>مقارنة متكافئة</b>، لا مقارنة أسهل مهمة بالأداة مع أصعب مهمة دونها. <b>وقت المراجعة</b> وتصحيح الاختبارات جزء من الكلفة. الهدف يجمع السرعة والجودة والالتزام بالبيانات حتى لا نكسب رقمًا ونخسر الأمان. إذا كانت النتيجة مولّدة فلا تُعاملها كدليل مستقل على نفسها؛ تحتاج مواصفات واختبارات ومراجعة من مصدر آخر.</p>'),
 S('SWOT und Kennzahlen im Beispiel','<p><b>Stärke:</b> vorhandenes Testwissen im Team; Schwäche: fehlende Erfahrung mit Werkzeuggrenzen. Chance: neue Automatisierungsmöglichkeiten am Markt; Risiko: geänderte Vertrags-/Datenschutzbedingungen eines Anbieters. Bei einer seltenen Fehlerklasse kann „99 % Genauigkeit“ wertlos sein, wenn ein System immer „kein Fehler“ meldet. Bei vorgegebenen Kennzahlen: <b>Precision</b> = richtig positive / alle positiv gemeldeten; <b>Recall</b> = richtig positive / alle tatsächlich positiven Fälle. Wähle nach den Folgen übersehener und falsch alarmierter Fälle.</p>','<p><b>مقياس واحد قد يخفي المشكلة</b>. في كشف الاحتيال اسأل كم حالة حقيقية اكتشفها النظام وكم اتهامًا كان خاطئًا. لا تحتاج بناء نموذج تعلم آلي للـAP2، لكن يجب تفسير فائدة التقنية وحدود أرقامها في حالة معطاة.</p>')
 ],Q('Ein Modell meldet 20 Fälle als Fehler, davon sind 15 wirklich Fehler. Insgesamt existieren 30 Fehler. Precision und Recall?','Precision = 15/20 = 75 %. Recall = 15/30 = 50 %. Ein Viertel der Meldungen ist falsch positiv, die Hälfte der echten Fehler wurde nicht gefunden.','احفظ المقام بحسب السؤال: كل المبلّغ عنه للدقة الإيجابية، وكل الموجود حقيقةً للاسترجاع.'));

 add('usecase',[
 S('Ein vollständiger Anwendungsfall aus einer Textaufgabe','<p>Ein Bibliothekssystem erlaubt Mitgliedern, Medien vorzumerken. Vor jeder Vormerkung wird die Berechtigung geprüft. Ist eine Benachrichtigung gewünscht, kann optional eine Nachricht über einen externen Maildienst gesendet werden. Mitarbeiter dürfen zusätzlich Vormerkungen für Mitglieder bearbeiten. Beginne mit der <b>Systemgrenze</b> „Bibliothekssystem“. Mitglied und Mitarbeiter sind Rollen außerhalb; auch der Maildienst ist als Fremdsystem ein <b>Akteur</b>. „Medium vormerken“ ist ein fachliches Ziel. „Berechtigung prüfen“ kann als wiederverwendeter Pflichtteil mit include eingebunden sein. Ein bedingter zusätzlicher Ablauf wird über extend mit geeigneter Bedingung am <b>Basisfall</b> modelliert.</p><p><b>Prüfe Rollenvererbung sorgfältig:</b> Dass Mitarbeiter Vormerkungen bearbeiten dürfen, bedeutet nicht automatisch, dass sie sämtliche Mitgliedsaktionen in derselben Rolle erben. <b>Generalisierung</b> ist nur richtig, wenn die <b>Spezialisierung</b> alle relevanten Beziehungen der allgemeinen Rolle übernimmt. Ergänze eine textuelle Beschreibung: Vorbedingung gültiges Mitglied, Auslöser Vormerkwunsch, Hauptablauf Berechtigung/Medium prüfen und Vormerkung speichern, Ausnahme Mitglied gesperrt, Nachbedingung genau eine fachlich gültige Vormerkung. So prüfst du, ob die grafische Übersicht inhaltlich vollständig ist.</p>','<p><b>ابدأ بتحديد من يقع خارج النظام</b>، ثم الأهداف التي يريدها، ثم العلاقات المتكررة أو الاختيارية. وجود موظف لا يعني تلقائيًا وراثته من عضو؛ اسأل هل كل علاقة العضو تنطبق عليه بصفته موظفًا؟ كذلك الرسالة البريدية ليست Actor، بل خدمة البريد الخارجية قد تكون Actor. النص المكمل يكشف ما لا يظهر في البيضويات: شروط البدء، أخطاء الحساب الموقوف، والنتيجة التي يجب أن تبقى بعد التنفيذ.</p>'),
 S('Pfeilrichtung aus der Bedeutung ableiten','<p><b>Merksatz include:</b> „A benutzt B als notwendigen Teil“ → A zeigt auf B. Merksatz extend: „E ergänzt A unter einer Bedingung“ → E zeigt auf A. Die zeitliche Reihenfolge einer Benutzeroberfläche ist kein Grund für include/extend. Eine einfache Verbindung <b>Akteur</b>–<b>Use Case</b> ist keine Datenflussrichtung. <b>Kurze Antwort:</b> „Berechtigung prüfen wird vom Vormerken inkludiert; Benachrichtigung ist eine bedingte Erweiterung. Die <b>Systemgrenze</b> trennt interne Funktionen von externen Rollen.“</p>','<p>اربط <b>اتجاه السهم</b> بجملة ذات معنى بدل حفظ اتجاه على الورقة. إذا لم تستطع شرح العلاقة بجملة «الحالة تستعمل الجزء» أو «الإضافة توسع الأصل»، فراجع هل العلاقة فعلًا مناسبة.</p>')
 ],Q('Ein Diagramm verbindet „Maske öffnen“ per include mit „Button klicken“. Warum ist das fachlich schwach?','Es modelliert GUI-Einzelschritte statt fachlicher Nutzerziele. Zunächst sinnvollen Anwendungsfall wie „Vormerkung erfassen“ bilden und erforderliche wiederverwendete Fachabläufe daraus ableiten.','حالات الاستخدام تصف هدف الاستخدام، وليست تسجيلًا لكل نقرة.'));
 add('klasse',[
 S('Vom Regeltext zum Klassendiagramm','<p><b>Regeln:</b> Ein Kurs hat genau einen verantwortlichen Dozenten und kann viele Anmeldungen besitzen. Jede Anmeldung gehört genau einem Kurs und einem Teilnehmer; sie speichert Anmeldedatum und Status. Ein Teilnehmer kann viele Anmeldungen haben. Daraus entstehen Dozent, Kurs, Teilnehmer und Anmeldung. Anmeldedatum gehört zu Anmeldung: Es hängt von der konkreten Kombination ab, nicht allein vom Teilnehmer oder Kurs.</p><p><b>Zeichne die <b>Multiplizitäten</b>:</b> Kurs→Dozent genau 1, Dozent→Kurs 0..*; Anmeldung→Kurs 1, Kurs→Anmeldung 0..*; Anmeldung→Teilnehmer 1, Teilnehmer→Anmeldung 0..*. Danach passende Attribute und Operationen ergänzen, z. B. Anmeldung.storniere() und Kurs.freiePlaetze(). Eine <b>Komposition</b> Kurs–Anmeldung kann sinnvoll sein, falls Anmeldungen keine eigenständige Lebensdauer außerhalb ihres Kurses haben; Archivierungsanforderungen können die Entscheidung aber beeinflussen. Die Diagrammnotation muss zur fachlichen Regel passen, nicht umgekehrt. Prüfe zum Schluss je Beziehung mit zwei Fragen: Wie viele B gehören zu einem A, und wie viele A zu einem B?</p>','<p><b>التحويل الجيد يحافظ على معنى المعلومات</b>. تاريخ التسجيل لا يخص الشخص عمومًا، بل تسجيله في دورة محددة. بعد رسم كل خط اقرأه في الاتجاهين مع مثال واحد حقيقي: هذا التسجيل لأي دورة؟ واحد فقط. هذه الدورة كم تسجيلًا؟ صفر أو أكثر. الملكية القوية ليست شرطًا لكل علاقة؛ تأكد من قواعد الحذف والأرشفة قبل اختيار الماسة الممتلئة.</p>'),
 S('Vererbung, Interface und Abhängigkeit präzise wählen','<p>Ein <b>Interface</b> Exporter definiert exportiere(daten). XMLExporter und CSVExporter realisieren es; gestrichelte Linie mit hohlem Dreieck zum <b>Interface</b>. Der Rechnungsdienst verwendet Exporter und muss den konkreten Typ nicht kennen. Eine gestrichelte <b>Abhängigkeit</b> zeigt Verwendung, keine Lebensdauerbindung. <b>Vererbung</b> ist fachlich stärker: Eine Unterklasse muss überall sinnvoll einsetzbar sein, wo der Basistyp erwartet wird. Gleiche Attribute allein sind kein ausreichender Grund.</p>','<p>اشتراك صنفين في حقل name لا يكفي ليَرث أحدهما الآخر. <b>الواجهة</b> تعبّر عن قدرة يمكن استبدال تنفيذها. هذا الفرق يساعدك أيضًا في ربط رسم UML بالبرمجة وتجنب رسم وراثة لكل علاقة استخدام.</p>')
 ],Q('Warum sollte das Anmeldedatum nicht einfach im Teilnehmer gespeichert werden, wenn er mehrere Kurse besucht?','Es gehört zu jeder konkreten Kursanmeldung und kann je Kurs verschieden sein. Ein einzelnes Teilnehmerattribut würde Werte verlieren oder Wiederholungsgruppen erzwingen; Anmeldung als eigene Beziehungsklasse modellieren.','اسأل دائمًا: إلى أي حدث أو علاقة تتبع قيمة هذا الحقل؟'));
 add('aktivitaet',[
 S('Bestellprozess mit Alternative und Parallelität','<p>Ein Bestellprozess startet mit „Eingabe prüfen“. Bei [ungültig] wird ein Fehler angezeigt und die Eingabe kann erneut erfolgen. Bei [gültig] beginnen „Bestand reservieren“ und „Zahlung prüfen“ parallel. Erst wenn beide erfolgreich abgeschlossen sind, wird „Bestellung bestätigen“ ausgeführt. Ein <b>Fork</b> startet die beiden parallelen Aktivitäten. Ein <b>Join</b> wartet auf die erforderlichen Abschlussflüsse. Erfolg und Fehler innerhalb der parallelen Aktivitäten brauchen definierte Wege: Scheitert die Zahlung, darf nicht einfach ein <b>Join</b> auf eine erfolgreiche Zahlung warten, die nie kommt.</p><p>Für einen einfachen Übungsentwurf kann nach dem <b>Join</b> eine Entscheidung beide Ergebnisse prüfen, sofern beide Prüfaktionen immer ein Ergebnis liefern. Bei [beide erfolgreich] bestätigen, sonst Reservierung aufheben und Ablehnung melden. Verantwortlichkeiten können in Lanes Kunde, Webanwendung, Zahlungsdienst getrennt werden. Prüfe jeden Startpfad bis zu einem sinnvollen Ende und stelle sicher, dass Schleifen erreichbar verlassen werden können. Das Diagramm ist ein Modell der spezifizierten Logik, keine Dekoration eines Textes.</p>','<p>الاختيار و<b>التوازي</b> يحلان مشكلتين مختلفتين. لا تبدأ تأكيد الطلب بعد أول نتيجة فقط، ولا تجعل <b>Join</b> ينتظر مسارًا لا يُنفذ في حالة الرفض. الحل الأبسط أن كلا نشاطي الفحص ينتجان نتيجة نجاح/فشل، ثم نزامنهما ونقرر. إذا ألغيت أحد المسارات مبكرًا فلابد أن توضّح كيف يتوقف الباقي وكيف تُزال حجزات المخزون؛ وإلا يخفي الرسم مشكلة حقيقية.</p>'),
 S('BPMN und EPK am selben Vorgang lesen','<p>In <b>BPMN</b> könnten Shop und Zahlungsanbieter verschiedene Pools sein: Anfrage und Antwort dazwischen sind Nachrichtenflüsse. Innerhalb des Shop-Pools verbinden Sequenzflüsse Aufgaben und Gateways. In <b>EPK</b> wechseln fachliche Ereignisse wie „Zahlung geprüft“ und Funktionen wie „Bestellung bestätigen“ mit passenden Konnektoren. Beim Beurteilen einer Digitalisierung nennen: welcher <b>Medienbruch</b> entfällt, welche Daten nun einmalig erfasst werden und welche Fehlerkontrolle nötig bleibt. „Alles automatisieren“ ist keine Prozessanalyse.</p>','<p>مثال التحسين ليس «استخدام برنامج» بل حذف إعادة إدخال بيانات الطلب من بريد إلى جدول، مع <b>تحقق آلي</b> من الحقول و<b>صلاحيات التعديل</b>. اذكر أثرًا واضحًا كزمن أقل أو أخطاء أقل، وحدًا مثل الحالات الاستثنائية التي تحتاج مراجعة بشرية.</p>')
 ],Q('Ein Zahlungspfad endet bei Fehler, während ein Join unverändert auf Zahlung und Bestand wartet. Welcher Fehler droht?','Der Join kann auf einen nie eintreffenden Abschluss warten. Fehler-/Abbruchbehandlung so modellieren, dass die Synchronisation fachlich definiert bleibt, z. B. beide Prüfungen liefern Status und danach wird gemeinsam entschieden.','المشكلة انتظار بلا نهاية، لا شكل الشريط وحده.'));
 add('sequenz-zustand',[
 S('Sequenz Schritt für Schritt: Cache mit Rückfall','<p>Die Oberfläche fragt beim Service den Preis für jede Warenkorbposition ab. Der Service prüft zunächst seinen <b>Cache</b>. Ist der Artikel dort vorhanden, kann er direkt einen Preis zurückgeben. Ist er nicht vorhanden, fragt er das <b>Repository</b>, übernimmt das Ergebnis in den <b>Cache</b> und gibt anschließend den Preis zurück. Ein loop-Fragment umfasst die wiederholten Positionsabfragen. Ein opt-Fragment mit [nicht im <b>Cache</b>] umfasst den zusätzlichen <b>Repository</b>-Zugriff; für explizit alternative Abläufe kann stattdessen ein alt-Fragment mit [im <b>Cache</b>] und [sonst] genutzt werden.</p><p><b>Die Reihenfolge ist entscheidend:</b> Erst nach Empfang des <b>Repository</b>-Ergebnisses steht der dort geladene Preis zur Verfügung. Ein <b>Cache</b>-Update könnte als <b>Selbstaufruf</b> des Service dargestellt werden. <b>Synchrone Nachrichten</b> warten auf Bearbeitung/Rückgabe; <b>asynchrone Nachrichten</b> erlauben dem Sender grundsätzlich weiterzuarbeiten. Beschrifte Methoden und Parameter passend zu den Verantwortlichkeiten. Ein Aufruf „SQL speichern“ direkt aus einer View kann im Diagramm sichtbar eine unerwünschte Umgehung der Fachlogik zeigen. Rückgaben nur einzeichnen, wenn sie wirklich von der gewählten Interaktion geliefert werden.</p>','<p>المخطط يحكي قصة تبادل معلومات بالزمن. لا يستطيع Service إعادة سعر لم يحصل عليه بعد. loop يكرّر معالجة عناصر السلة، وopt يضيف طريق القاعدة عندما لا يوجد <b>cache</b>. إذا أردت إظهار المسارين بوضوح فاستعمل alt بشروط متكاملة. Self-call يعود للكائن نفسه، وليس إلى كائن ثانٍ له الاسم نفسه. الهدف أن تستطيع تتبّع مصدر كل قيمة ومتى صارت متاحة.</p>'),
 S('Zustandsautomat: ein Ereignis kann je Zustand anders wirken','<p>„stornieren“ darf eine Rechnung im Entwurf verwerfen, eine exportierte Rechnung aber nicht einfach löschen. Deshalb ist der aktuelle Zustand Teil der Regel. <b>entry</b>-Aktionen laufen bei jedem tatsächlichen Eintritt erneut, <b>exit</b> beim Austritt; ein externer Selbstübergang kann beide auslösen. Eine interne Behandlung kann sich davon unterscheiden. do beschreibt Verhalten während des Zustands, kein automatisch sofort abgeschlossenes Übergangseffekt. Prüfe mindestens erlaubte Übergänge, falschen <b>Guard</b> und unzulässiges Ereignis. Die Kürze eines Übergangsetiketts ersetzt nicht die Definition dieser Fälle.</p>','<p>إذا أرسل المستخدم نفس الفعل من حالتين مختلفتين فقد تكون النتيجة مختلفة. لهذا نختبر الحالة مع الحدث، لا الحدث وحده. وزمن التنفيذ يميّز <b>entry</b> وdo وexit عن الأثر بعد / في الانتقال. هذه التفاصيل تفسر رسمًا امتحانيًا بدل الاكتفاء بحفظ أسماء الرموز.</p>')
 ],Q('Ein Artikel ist im Cache. Welche Nachrichten entfallen im dargestellten loop/opt-Beispiel, welche bleiben?','Der Repository-Aufruf und dessen Rückgabe innerhalb opt entfallen. Der Aufruf UI→Service sowie die Preisrückgabe Service→UI bleiben bestehen; die Schleife läuft für die nächste Position weiter.','عدم تنفيذ الكتلة الاختيارية لا يعني تخطي معالجة العنصر كله.'));
 add('architektur',[
 S('Strategy vollständig anwenden','<p>Ein Shop berechnet Versand per Standarddienst, Express oder Abholung. Eine große if-Kette im Auftrag mischt Versandregeln mit Bestellverwaltung. Wir definieren stattdessen ein <b>Interface</b> mit berechne(gewicht,wert). Die Auftragserzeugung wählt eine passende Strategie und übergibt sie. Der Auftrag delegiert die Rechnung, ohne jeden konkreten Versandtyp zu kennen. Neue Regeln können durch eine neue Implementierung ergänzt werden; bestehende Bestelllogik muss nicht umgeschrieben werden.</p>'+C('interface Versandstrategie:\n  berechne(gewicht, warenwert): Decimal\n\nklasse Standard implementiert Versandstrategie:\n  berechne(gewicht, warenwert):\n    wenn warenwert >= 100: rückgabe 0\n    rückgabe 4 + gewicht * 0.5\n\nklasse Express implementiert Versandstrategie:\n  berechne(gewicht, warenwert): rückgabe 12 + gewicht\n\nklasse Auftrag:\n  konstruktor(strategie): self.strategie = strategie\n  versandpreis(gewicht, wert):\n    rückgabe self.strategie.berechne(gewicht, wert)')+'<p><b>Die Vorteile haben Kosten:</b> mehr kleine Typen und eine Stelle für ihre Auswahl. Für zwei unveränderliche sehr einfache Fälle ist eine direkte Fallunterscheidung möglicherweise ausreichend. Gute Architektur hält Komplexität passend zum Änderungsbedarf.</p>','<p><b>العقد يوحّد طريقة السؤال عن السعر</b>، والتنفيذات تحوي الاختلاف. Auftrag لا يعرف تفاصيل Standard وExpress؛ هذا فصل للمسؤولية واعتماد على abstraction. الإضافة الجديدة لا تعني غالبًا عدم تغيير أي سطر في النظام إطلاقًا، فقد تتغير تهيئة الاختيار؛ المقصود تقليل التعديل في منطق الأعمال المستقر. لا تنشئ عشرات الأصناف بلا سبب إذا لا توجد حاجة تبديل أو نمو.</p>'),
 S('Factory, Adapter und Schichten daran abgrenzen','<p>Factory beantwortet, wie das passende Objekt erzeugt wird; <b>Strategy</b>, welches austauschbare Verhalten benutzt wird. Adapter passt eine vorhandene fremde API an unser <b>Interface</b> an. Die Serviceschicht koordiniert einen Anwendungsfall, die Domäne enthält fachliche Regeln, das <b>Repository</b> abstrahiert Datenzugriff. Eine Webseite mit drei Verzeichnissen ist dadurch noch keine echte <b>Drei-Schichten-Architektur</b>: Entscheidend sind Verantwortlichkeiten und zulässige Abhängigkeiten. Bei <b>Microservices</b> kommen Netzfehler, Versionsabstimmung und verteilte Datenhaltung hinzu.</p>','<p>قد تجمع الحلول أكثر من نمط لأن كلًا منها يعالج سؤالًا مختلفًا. افصل إنشاء كائن الدفع عن تنفيذ الدفع، وعن ترجمة API قديم إلى واجهتك. وعند اختيار <b>Microservices</b> اذكر كلفة الاتصال والتشغيل، لا فوائد التقسيم فقط.</p>')
 ],Q('Ein Fremdanbieter bietet sendePaket(adresse,gramm), dein System erwartet versende(empfaenger,kilogramm). Welches Muster passt und welche Logik enthält es?','Adapter: setzt die Empfängerstruktur um, rechnet kg in g und ruft die fremde Operation auf. Er übersetzt außerdem Rückgaben/Fehler in den eigenen Vertrag; die restliche Fachlogik kann das vorhandene Interface nutzen.','التكييف يشمل معنى البيانات ووحداتها وأخطاءها، لا تغيير اسم الدالة فقط.'));

 add('grundlagen-code',[
 S('Eine kleine Funktion vollständig durchdenken','<p><b>Aufgabe:</b> Ein Rabatt von 10 % gilt nur für Kunden mit mindestens fünf gekauften Einheiten und aktivem Kundenkonto. Die Menge muss eine positive ganze Zahl sein, der Einzelpreis darf nicht negativ sein. Definiere zunächst das Ergebnis als Nettobetrag in Cent; dadurch vermeidest du hier typische Binär-<b>Gleitkommaprobleme</b>. Ein Rabatt kann dennoch Rundung benötigen, deshalb wird die Rundungsregel ausdrücklich angegeben: auf ganze Cent <b>kaufmännisch runden</b>.</p>'+C('funktion betrag(menge, preisCent, aktiv):\n  wenn menge <= 0 ODER menge ist nicht ganzzahlig ODER preisCent < 0:\n    Fehler "ungültige Eingabe"\n  basis = menge * preisCent\n  wenn menge >= 5 UND aktiv:\n    rückgabe rundeAufGanzeCent(basis * 0.90)\n  rückgabe basis')+'<p><b>Für Menge 5, Preis 999 Cent und aktiv=true:</b> Basis 4.995 Cent, nach Rabatt 4.495,5 Cent, gerundet 4.496 Cent. Für aktiv=false bleibt die Basis unverändert. Wichtige Grenzen sind Menge 4/5/6, ungültige Menge 0 und ein Preis von 0. Die Gültigkeitsprüfung erfolgt vor der Berechnung; das Verhalten bei ungültigen Eingaben wird nicht dem Zufall überlassen.</p>','<p>المنطق يحتوي شرط قبول للبيانات وشرط استحقاق الخصم، وهما ليسا شيئًا واحدًا. مقدار صفر غير صالح، بينما سعر صفر قد يكون صالحًا حسب المواصفة. تمثيل المال بالسنت يقلل مشكلة <b>الأرقام العائمة</b> لكنه لا يلغي الحاجة لتحديد التقريب عند نسبة خصم. تابع قيمة basis ثم النتيجة في كل فرع، ولا تقل فقط «هناك if». الاختبارات حول 5 تكشف الفرق بين > و≥، واختبار حساب غير نشط يكشف استعمال OR بدل AND.</p>'),
 S('Kurzschluss und leere Werte','<p>Bei <code>x != null AND x.preis &gt; 0</code> darf der zweite Zugriff bei <b>Kurzschlussauswertung</b> nur stattfinden, wenn x vorhanden ist. Ist diese Semantik in Pseudocode nicht klar, teile die Prüfung in zwei if-Schritte. Leere Zeichenkette, Leerzeichen und null sind verschiedene Eingaben; ein Formular kann trim benötigen, ohne NULL dadurch automatisch zu behandeln. Bei einer for-Schleife mit n Elementen und <b>Nullindexierung</b> gilt meist i&lt;n, nicht i≤n. Schleifenvariable, Abbruchbedingung und Fortschritt gemeinsam prüfen.</p>','<p><b>الاختصار في التقييم</b> يحمي الوصول إلى كائن غير موجود فقط إذا كانت اللغة/الصياغة تضمنه. أوضح الحل عند الحاجة بفحص منفصل، فهذا أفضل من الاعتماد على افتراض خفي. كذلك " " ليست نصًا فارغًا قبل إزالة الفراغات.</p>')
 ],Q('Im Rabattbeispiel wurde AND versehentlich durch OR ersetzt. Welche zwei Eingaben zeigen den Fehler?','Menge 1 mit aktiv=true sowie Menge 5 mit aktiv=false: beide würden fälschlich Rabatt erhalten. Korrekt brauchen beide Teilbedingungen gleichzeitig wahr zu sein.','اختبر حالة يصدق فيها كل شرط وحده؛ هذا يميز OR من AND بوضوح.'));
 add('datenstrukturen',[
 S('Häufigkeiten mit einer Map aufbauen','<p>Gegeben sind verkaufte Kategorien in der Reihenfolge [Buch,Spiel,Buch,Musik,Spiel,Buch]. Gesucht ist die <b>Anzahl</b> pro Kategorie, ohne für jede Kategorie erneut die ganze Liste zu durchlaufen. Eine <b>Map</b> speichert <b>Kategorie→<b>Anzahl</b></b>. Bei jedem Element wird der bisherige Wert gelesen; ein fehlender Schlüssel bedeutet für diese Zählaufgabe 0. Danach wird 1 addiert. Nach den ersten drei Elementen lautet die <b>Map</b> Buch→2, Spiel→1. Am Ende Buch→3, Spiel→2, Musik→1.</p>'+C('haeufigkeit = leere Map\nfür kategorie in kategorien:\n  bisher = haeufigkeit.getOderStandard(kategorie, 0)\n  haeufigkeit[kategorie] = bisher + 1')+'<p>Wegen des typischerweise <b>Durchschnitt</b>lich konstanten Hash-Zugriffs ist die <b>Gesamtlaufzeit</b> im üblichen Modell <b>Durchschnitt</b>lich <b>O(n)</b>. Ergebnisreihenfolge ist nicht automatisch alphabetisch; soll sie so sein, müssen die Schlüssel zusätzlich sortiert werden. Beachte außerdem die fachliche Gleichheit: „Buch“ und „buch“ sind zunächst verschiedene Zeichenketten. Eine Normalisierung muss spezifiziert sein, damit nicht unbeabsichtigt verschiedene Kategorien verschmolzen werden.</p>','<p>الـ<b>Map</b> تمنع الحاجة لحلقة ثانية تبحث عن كل فئة في قائمة النتائج. لكن المفتاح يجب أن يكون متسقًا: هل الحروف الكبيرة مهمة؟ وهل توجد فراغات زائدة؟ حدّد ذلك قبل العد. لا تفترض أن ترتيب الخرج هو ترتيب أبجدي أو ترتيب الإدخال لكل تنفيذ <b>Map</b>. النتيجة الصحيحة عدديًا قد تظل تخالف مواصفة ترتيب التقرير إذا أهملته.</p>'),
 S('Stack und Queue wirklich ausführen','<p><b><b>Stack</b> nach push(A), push(B), pop():</b> Rückgabe B, Rest [A]. <b>Queue</b> nach enqueue(A), enqueue(B), dequeue(): Rückgabe A, Rest [B]. Bei leerer Struktur muss der Vertrag Fehler/kein Ergebnis definieren. Eine Undo-Funktion braucht oft zusätzlich gespeicherte Informationen zur Gegenoperation, nicht nur den Namen einer Aktion. Eine Warteschlange kann Rückstau erzeugen; Prioritäten würden eine andere Auswahlregel als reines <b>FIFO</b> verlangen.</p>','<p>اختيار <b>Stack</b> لا يكتب Undo تلقائيًا؛ يجب حفظ الحالة أو المعلومات التي تسمح بالعكس. وبالمثل <b>Queue</b> لا تضمن سرعة الإنجاز؛ هي قاعدة ترتيب. اشرح العملية على عناصر فعلية لتثبت فهمك بدل حفظ <b>LIFO</b>/<b>FIFO</b> فقط.</p>')
 ],Q('Kategorien [A,B,A] sollen gezählt und alphabetisch ausgegeben werden. Welche zwei Phasen braucht der Algorithmus?','Zuerst eine Map A→2, B→1 aufbauen. Danach die Schlüssel sortieren und in dieser Reihenfolge mit ihren Anzahlen ausgeben. Hash-Zählung allein garantiert die alphabetische Ausgabe nicht.','العد والترتيب مطلبان مستقلان؛ لا تعتمد على مصادفة ترتيب البنية.'));
 add('algo-muster',[
 S('Verarbeitung mit Filtern, Zählern und sauberem Ergebnis','<p><b>Aufgabe:</b> Bestellungen enthalten kundeId, betrag und status. Für jeden Kunden soll der Durchschnitt gültiger bezahlter Bestellungen berechnet werden. Stornierte Bestellungen zählen nicht; negative Beträge gelten in dieser Aufgabe als Datenfehler. Eine einzige Map nur mit Durchschnitt ist ungeeignet, weil beim nächsten Wert die bisherige Anzahl fehlt. Speichere pro Kunde Summe und Anzahl. Am Ende wird die Summe durch die zugehörige Anzahl geteilt.</p>'+C('gruppen = leere Map\nfehler = leere Liste\nfür b in bestellungen:\n  wenn b.betrag < 0:\n    fehler.hinzufuegen(b)\n  sonst wenn b.status == "bezahlt":\n    wenn b.kundeId nicht in gruppen:\n      gruppen[b.kundeId] = {summe: 0, anzahl: 0}\n    gruppen[b.kundeId].summe += b.betrag\n    gruppen[b.kundeId].anzahl += 1\nergebnis = leere Map\nfür id, g in gruppen:\n  ergebnis[id] = g.summe / g.anzahl')+'<p><b>Bei A:</b> 20 bezahlt, 40 bezahlt, 100 storniert ergibt sich 30, nicht 160/3. Kunden ohne gültige bezahlte Bestellung erscheinen hier nicht; sollen sie mit einem besonderen Wert erscheinen, muss die Aufgabenstellung eine Kundenliste und eine Regel dafür liefern. Ein fehlender Durchschnitt ist nicht automatisch 0.</p>','<p>الخطأ الشائع حساب «<b>متوسط متحرك</b>» بأخذ متوسط القديم والجديد؛ هذا لا يعطي المتوسط الصحيح بعد أكثر من قيمتين. احتفظ بمجموع وعدد، وصفِّ البيانات قبل زيادتهما. حدّد أيضًا ما الذي يعنيه غياب عميل من النتيجة. صفر متوسط ومعدل غير معرّف لغياب طلبات ليسا الشيء نفسه، حتى لو اختار العرض النصي إظهار علامة بديلة لكليهما.</p>'),
 S('Ablaufverfolgung statt Bauchgefühl','<p>Erstelle eine Tabelle mit Eingabe, Statusprüfung, bisheriger Summe und Anzahl. Prüfe die <b>Invariante</b>: Nach k verarbeiteten Datensätzen entsprechen Summe/Anzahl genau den bisher akzeptierten Werten. Solche einfachen Invarianten helfen Fehler zu lokalisieren. Bei Maximum/Minimum gilt entsprechend: Die bisherige Auswahl ist das beste der bereits geprüften gültigen Elemente. Ein früher Return innerhalb einer Schleife ist nur richtig, wenn spätere Elemente das Ergebnis nicht mehr ändern können.</p>','<p><b>Invariante</b> جملة تظل صحيحة بعد كل دورة. استخدامها يجعل المراجعة منهجية: إذا اختل العدد في الدورة الثالثة فالمشكلة بدأت هناك، لا عند القسمة الأخيرة. وreturn مبكر قد يعيد أول مرشح بدل أفضل مرشح إذا كان المطلوب مقارنة الجميع.</p>')
 ],Q('Warum ist (bisherigerDurchschnitt + neuerWert)/2 bei einer beliebig langen Liste falsch?','Es gewichtet den neuen Wert genauso stark wie alle bisherigen Werte zusammen. Korrekt Summe und Anzahl speichern bzw. einen mathematisch korrekt gewichteten Online-Durchschnitt verwenden. Beispiel 10,20,30: falsche Folge ergibt 22,5 statt 20.','المشكلة وزن القيم، لا صيغة القسمة وحدها.'));
 add('suchen-sortieren',[
 S('Binäre Suche mit Wertetabelle','<p>Sortiertes Array [3,8,12,19,27,31,44], gesucht 27. Anfang links=0, rechts=6. Mitte=3, Wert 19; 27 ist größer, also bleibt nur rechts davon: links=4. Neue Mitte=5, Wert 31; gesucht ist kleiner, also rechts=4. Nun Mitte=4, Wert 27: gefunden. Bei gesuchtem 28 endet die Suche schließlich mit links&gt;rechts und liefert „nicht gefunden“. Der mittlere Index selbst wird nach einer ungleichen Prüfung ausgeschlossen; sonst kann eine <b>Endlosschleife</b> entstehen.</p><p>Die Voraussetzung ist nicht nur „irgendeine Liste“, sondern eine passende Sortierreihenfolge und effizienter Zugriff auf die Mitte. Muss eine unsortierte kleine Liste nur einmal durchsucht werden, kann Sortieren plus <b>binäre Suche</b> mehr Aufwand bedeuten als eine <b>lineare Suche</b>. Big O hilft Alternativen beurteilen, ersetzt aber nicht die Kenntnis des Zugriffsfalls.</p>','<p><b>تتبّع الحدود كقيم لا كشكل رسم فقط</b>. بعد استبعاد Mitte نزيده أو ننقصه واحدًا في الحدود الجديدة حتى يتقدّم الحل. ترتيب القائمة شرط أساسي؛ لو كان 27 قبل 19 في بيانات غير مرتبة فقد نستبعد المكان الصحيح. واختيار الخوارزمية يعتمد عدد مرات البحث وكلفة تحضير البيانات، لا على أن log n يبدو أصغر دائمًا.</p>'),
 S('Insertion Sort und Rekursion nachvollziehen','<p><b><b>Insertion Sort</b> auf [5,2,4]:</b> Beginne mit sortiertem Präfix [5]. Nimm 2, verschiebe 5 nach rechts und setze 2 vorn: [2,5,4]. Nimm 4, verschiebe nur 5: [2,4,5]. Fakultät rekursiv: f(3)=3×f(2), f(2)=2×f(1), f(1)=1×f(0), f(0)=1. Beim Zurückkehren entstehen 1,1,2,6. Ein Abstieg ohne <b>Basisfall</b> verbraucht weiter <b>Stack</b>; ein <b>Basisfall</b>, der nie erreicht wird, hilft ebenso wenig. Für negative Eingaben muss das Beispiel die Gültigkeit vorher prüfen.</p>','<p><b>في recursion توجد مرحلة نزول للاستدعاءات ومرحلة عودة لتركيب النتائج</b>. لا تقل إن f(3) يساوي 3 مباشرة لأنك وصلت إليه؛ انتظر نتيجة f(2). وفي Insertion يتم تحريك العناصر الأكبر لإفساح مكان للعنصر، لا اختيار أصغر الباقي كما في Selection.</p>')
 ],Q('Bei binärer Suche wird nach a[mitte] < gesucht nur links = mitte gesetzt. Welches Problem kann auftreten?','Bei einem kleinen verbleibenden Bereich kann mitte wieder denselben Index ergeben, sodass die Grenzen nicht mehr schrumpfen. links = mitte+1 schließt den bereits als zu klein erkannten Wert aus.','كل دورة يجب أن تصغّر مجال البحث إذا لم تجد القيمة.'));
 add('oop',[
 S('Ein Interface im Programm statt nur als Begriff','<p>Ein Rechnungsdienst soll <b>XML</b> und <b>CSV</b> exportieren. Wir definieren einen Exportvertrag, während die konkreten Implementierungen das Format übernehmen. Der Dienst erhält den Exporter über seinen <b>Konstruktor</b>. Damit entscheidet nicht jede Rechnung selbst per Typabfrage über ihr Ausgabeformat. Ein Test kann einen einfachen FakeExporter einsetzen und prüfen, welche Daten übergeben wurden.</p>'+C('interface Exporter:\n  exportiere(rechnung): Text\n\nklasse CSVExporter implementiert Exporter:\n  exportiere(r):\n    rückgabe formatiereAlsCSV(r)\n\nklasse XMLExporter implementiert Exporter:\n  exportiere(r):\n    rückgabe formatiereAlsXML(r)\n\nklasse Rechnungsdienst:\n  konstruktor(exporter): self.exporter = exporter\n  ausgabe(rechnung):\n    pruefeFachlicheGueltigkeit(rechnung)\n    rückgabe self.exporter.exportiere(rechnung)')+'<p><b><b>Polymorphie</b> zeigt sich beim letzten Aufruf:</b> Welcher Code läuft, hängt vom konkreten übergebenen Objekt ab, obwohl der Dienst nur den Vertrag kennt. Die fachliche Gültigkeit gehört weiterhin an einen bewusst gewählten Ort. Ein <b>Interface</b> allein sorgt nicht dafür, dass <b>CSV</b> und <b>XML</b> dieselben fachlichen Daten verwenden; das wird spezifiziert und getestet.</p>','<p><b>الواجهة</b> وعد بسلوك؛ وليست ضمانًا سحريًا لتنفيذ صحيح. XMLExporter وCSVExporter يقبلان المدخل المنطقي نفسه ويخرجان نصًا بصيغة مختلفة. تمرير الاعتماد في <b>Konstruktor</b> يجعل الاختبار والاستبدال أوضح. يظل على الخدمة التحقق من صحة الفاتورة وفق المسؤولية المعرّفة، ولا تكرر هذه القاعدة عشوائيًا في كل شاشة وتصدير.</p>'),
 S('Verträge und Exceptions','<p>Ein Untertyp darf den erwarteten Vertrag nicht überraschend verschärfen. Wenn Exporter gültige Rechnungen akzeptiert, darf eine Implementierung nicht ohne dokumentierte Grundlage nur Rechnungen unter 10 € verarbeiten. Fehler müssen zur Schnittstelle passen: Eine ungültige Rechnung kann einen definierten Validierungsfehler liefern; ein technischer Fehler wird nicht als leerer erfolgreicher Export getarnt. <b>Methodenüberladung</b> unterscheidet Signaturen, <b>Überschreiben</b> die Implementierung einer geerbten Operation. Beide Konzepte können im selben Programm vorkommen, lösen aber unterschiedliche Auswahlfragen.</p>','<p><b>إذا كان المستدعي يتوقع معالجة أي فاتورة صالحة ثم فشل أحد الأنواع بسبب شرط خفي، يكون الاستبدال معطوبًا</b>. null أو نص فارغ قد يبدوان نجاحًا زائفًا إن لم يحدد العقد معناهما. اجعل الفشل قابلًا للفهم والمعالجة.</p>')
 ],Q('Ein Exporter fängt alle Fehler und gibt dann einen leeren String zurück, der als erfolgreiche Datei gespeichert wird. Was ist problematisch?','Der Fehler wird als Erfolg maskiert und kann zu Datenverlust/fehlerhafter Weiterverarbeitung führen. Einen definierten Fehlerpfad/Exception oder expliziten Result-Typ verwenden und Aufrufer sachgerecht reagieren lassen.','معالجة الاستثناء لا تعني إخفاءه وإعادة نتيجة مضللة.'));
 add('sprachen-cps',[
 S('Datenimport: vom Text zur fachlichen Information','<p>Eine <b>CSV</b>-Zeile lautet <code>4711;2;12,50</code>. Ohne Datenvertrag ist unklar, ob 4711 Artikel oder Kunde bezeichnet und ob 12,50 Stückpreis oder Gesamtsumme ist. Lege Spaltenreihenfolge, Trennzeichen, Anführungsregeln, Encoding, Dezimalformat und Pflichtfelder fest. Danach folgen getrennte Schritte: Text zerlegen, Strukturzahl prüfen, Werte in Typen umwandeln, Wertebereiche prüfen, referenzierte Objekte prüfen und erst dann Daten speichern. Eine Zeile mit zwei statt drei Feldern ist ein Strukturproblem; eine Menge −2 bei verbotenen Retouren ist ein fachlicher Fehler.</p><p>Bei <b>XML</b> prüft ein Parser <b>Wohlgeformtheit</b>; eine <b>XSD-Prüfung</b> kann zusätzlich Elementreihenfolge, Datentypen und <b>Kardinalitäten</b> einschränken. Eine Rechnung kann diese Prüfung bestehen und trotzdem eine falsch berechnete Summe enthalten. Bei <b>JSON</b> definiert die Syntax allein ebenfalls keinen Geschäftsvertrag. Protokolliere Zeilennummer und Grund eines Fehlers, ohne unnötig sensible Rohdaten zu vervielfältigen. Entscheide, ob der gesamte Import atomar fehlschlägt oder gültige Zeilen mit gesonderter Fehlerliste übernommen werden.</p>','<p><b>البيانات ليست نصًا بأرقام فقط</b>؛ المعنى جزء من الاتفاق. قسم الفشل إلى شكل غير صالح، وتحويل نوع فاشل، وقيمة خارج المجال، ومرجع غير موجود. بذلك يصبح الخطأ قابلًا للتصحيح. قرار قبول السطور الصحيحة ورفض غيرها يختلف عن «الكل أو لا شيء»؛ لا تفترضه دون مواصفة لأن الأنظمة المالية قد تحتاج اتساق الملف كاملًا.</p>'),
 S('CPS: Abfragerhythmus und Hysterese begründen','<p>Ein Temperatursensor liefert Zehntelgrad. Das Steuerprogramm liest den Wert, prüft den plausiblen Bereich und wandelt ihn in °C um. Ein Lüfter startet ab 28 °C und stoppt unter 26 °C. Die getrennten Grenzen verhindern schnelles Umschalten bei Messrauschen um 28 °C. Der <b>Abfragerhythmus</b> hängt von Änderungsdynamik, Reaktionszeit, Energieverbrauch und Kommunikationslast ab. Bibliothek, Einheit und Fehlerwert des Sensors müssen bekannt sein; ein fehlgeschlagener Messwert ist nicht „0 °C“.</p>','<p><b>اختيار الحساس يشمل مدى القياس ودقته وسرعة الاستجابة وواجهة الوصول</b>. قراءة كل ميلي ثانية لا تفيد غرفة يتغير حرارها ببطء وقد تهدر موارد؛ في تحكم سريع قد تكون ثانية طويلة جدًا. لكل عطل يجب تحديد سلوك آمن مناسب للحالة بدل قرار عشوائي.</p>')
 ],Q('Ein Sensor liefert bei Fehler −9999, ansonsten Zehntelgrad. Warum ist bloßes Teilen durch 10 nicht ausreichend?','−9999 ist ein Fehlercode, keine echte Temperatur. Vor Umrechnung und Steuerentscheidung den Status/Fehlerwert prüfen, Fehler melden und den definierten sicheren Betriebszustand wählen.','تحويل قيمة خطأ إلى −999.9° لا يجعلها قياسًا صالحًا.'));
 add('algo-buchung',[
 S('Das Buchungsbeispiel manuell durchrechnen','<p><b>Wunsch:</b> 10 Personen von 10:00 bis 11:00. Räume: A mit 8, B mit 12, C mit 20, D mit 12 Plätzen; bei gleicher Kapazität hat B die kleinere ID. Buchungen: B von 09:00 bis 10:00, C von 10:30 bis 12:00, D von 09:30 bis 10:30. A scheidet vor der inneren Schleife aus, weil 8&lt;10. B ist groß genug. Sein bisheriger Termin endet exakt um Wunschbeginn: b.start&lt;w.ende ist wahr, w.start&lt;b.ende ist 10:00&lt;10:00 und damit falsch. Kein Konflikt, B wird bester Kandidat.</p><p><b>C überschneidet sich von 10:</b>30 bis 11:00 und wird ausgeschlossen; D von 10:00 bis 10:30 ebenso. Ergebnis B. Werden alle Buchungen entfernt, bleiben B und D die gleich großen besten Kandidaten; die ID-Regel entscheidet für B. Damit ist der Algorithmus unabhängig von zufälliger Listenreihenfolge. Prüfe auch eine Buchung, die den gesamten Wunsch umschließt: Anfang davor und Ende danach erfüllt beide Überlappungsbedingungen. Ein bloßer Test „Start liegt im Wunsch“ würde diesen Konflikt übersehen.</p>','<p><b>الجزء الأصعب أن نتعامل مع جميع أشكال التداخل:</b> بدء حجز أثناء الطلب، انتهاؤه أثناءه، أو إحاطته به كاملًا. الشرط ذو المقارنتين يغطيها مع فرض start&lt;end. B لا يتعارض رغم تلامس الزمن لأن النهاية غير مشمولة. اكتب جدول المرشحين: سعة كافية؟ تعارض موجود؟ أفضل من السابق؟ بهذه الطريقة تعرف هل الخطأ في الفلترة أم الاختيار أم الحدود.</p>'),
 S('Schrittweise entwerfen und die innere Schleife verstehen','<p>Man kann die Konfliktprüfung in <code>istFrei(raum,buchungen,wunsch)</code> auslagern. Diese Funktion gibt beim ersten passenden Konflikt false zurück und erst <em>nach</em> der gesamten Schleife true. Das ist ein wesentlicher Unterschied zur falschen Version, die schon nach der ersten fremden oder konfliktfreien Buchung true liefert. Für R Räume und B Buchungen ist der einfache Worst Case <b>O(R×B)</b>; eine nach Raum gruppierte Struktur kann unnötige Prüfungen verringern, setzt aber zusätzlichen Speicher/Aufbau voraus.</p>','<p><b>return false مبكرًا صحيح لأن تعارضًا واحدًا يكفي للرفض</b>. return true مبكرًا غير صحيح لأن خلو حجز واحد لا يكفي للقبول. سبب الفرق منطق كمي: «يوجد تعارض» مقابل «لا يوجد أي تعارض». فهمه يساعد في مسائل تحقق أخرى كثيرة.</p>')
 ],Q('Eine Buchung 08:00–13:00 und ein Wunsch 10:00–11:00. Ein Programm prüft nur, ob der Buchungsbeginn zwischen Wunschbeginn und Wunschende liegt. Ergebnisproblem?','Es übersieht die umschließende Buchung, da 08:00 nicht im Wunsch liegt. Korrekt ist b.start < w.ende AND w.start < b.ende; beide Bedingungen sind hier wahr.','لا تختبر شكلًا واحدًا للتداخل وتعتبره كل الحالات.'));
 COURSE.lessons.find(l=>l.id==='sprachen-cps').sections.push(S('E-Rechnung: strukturiert ist mehr als digital sichtbar','<p>Eine als normale PDF versandte Rechnung ist für Menschen lesbar, enthält aber nicht automatisch den strukturierten Datensatz für eine definierte maschinelle Weiterverarbeitung. <b>XRechnung</b> ist ein strukturiertes <b>XML</b>-basiertes Format; geeignete <b>ZUGFeRD</b>-Profile können eine lesbare PDF-Darstellung mit eingebetteten strukturierten Rechnungsdaten verbinden. Für die Softwareaufgabe bedeutet das: Datenmodell, Schema, fachliche Summenprüfung und Importfähigkeit gemeinsam betrachten. Die steuerlichen Pflichten, Ausnahmen und Übergangsfristen sind separat nach der aktuellen Rechtslage zu prüfen; hier steht das technische Verständnis im Vordergrund.</p>','<p>المهم في <b>الفاتورة الإلكترونية</b> المطلوبة تقنيًا ليس وصول ملف عبر البريد فقط. PDF عادي يوضح المبلغ للإنسان؛ <b>البيانات المنظمة</b> تتيح للنظام تمييز رقم الفاتورة والضريبة والمجموع دون إعادة إدخال. الملف الهجين يجمع العرض البشري والبيانات الآلية، ولا يلغي فحص توافق الجزأين وصحة المجاميع.</p>'));
 COURSE.sources.push(['erechnung','BMF: E-Rechnung und Formate','https://www.bundesfinanzministerium.de/Content/DE/FAQ/e-rechnung.html','Unterscheidung strukturierter Rechnungsdaten und bloßer PDF-Darstellung; keine pauschale Aussage zu jeder Steuer-/Übergangsregel.']);
 COURSE.lessons.find(l=>l.id==='sprachen-cps').sources.push('erechnung');
 COURSE.lessons.find(l=>l.id==='sicherheitsrisiken').sections.push(S('Organisation der Sicherheit: ISMS und Grundschutz','<p>Ein Informationssicherheitsmanagementsystem (<b>ISMS</b>) organisiert Schutz systematisch: Geltungsbereich und <b>Verantwortliche</b> festlegen, Informationswerte/Risiken beurteilen, Maßnahmen planen, umsetzen, prüfen und verbessern. <b>ISO/IEC 27001</b> beschreibt Anforderungen an ein solches Managementsystem; das BSI bietet mit <b>IT-Grundschutz</b> ein methodisches Vorgehen und Bausteine für typische Sicherheitsanforderungen. Das Bundesamt für Sicherheit in der Informationstechnik unterstützt Cybersicherheit unter anderem durch Informationen, Empfehlungen, Standards, Warnungen und Zertifizierung im gesetzlichen Aufgabenbereich. Ein <b>Zertifikat</b> ist kein Beweis, dass eine einzelne Anwendung ohne Schwachstellen ist; Geltungsbereich und laufende Umsetzung zählen.</p>','<p><b>ISMS</b> ليس برنامج Antivirus، بل طريقة إدارة مستمرة: من المسؤول، ما الأصول، ما الخطر، ما الإجراء، وكيف نراجع النتيجة؟ المعيار يساعد تنظيم العمل ولا يعفي من فحص كود التطبيق أو حقوق الوصول. وعند ذكر شهادة اسأل ماذا شملت ومتى، بدل اعتبارها ضمانًا مطلقًا لكل وظيفة.</p>'));
 COURSE.lessons.find(l=>l.id==='testarten').sections.push(S('Prüfwerte, Parität und Redundanz richtig einordnen','<p>Ein <b>Paritätsbit</b> ergänzt Daten so, dass die Anzahl gesetzter Bits gerade oder ungerade ist. Ein einfacher <b>Paritätstest</b> erkennt eine ungerade Zahl gekippter Bits, aber nicht jede gerade Zahl; er korrigiert nicht allgemein den Fehler. Eine <b>Prüfsumme</b>/CRC hilft zufällige Übertragungsfehler zu erkennen, ist aber kein Ersatz für kryptografische Authentizität. <b>Redundanz</b> bedeutet zusätzliche Information oder Ressourcen; ihr Nutzen hängt vom Fehlerbild ab. Eine Spiegelung kann <b>Verfügbarkeit</b> erhöhen, spiegelt aber auch fehlerhafte Anwendungsänderungen. Beschreibe deshalb immer, welche Art von Fehler eine Maßnahme erkennen, verhindern oder überbrücken kann.</p>','<p><b>وجود معلومة زائدة لا</b> يعني حماية كاملة. Parität بسيط قد لا يكتشف قلب بتّين لأن زوجية المجموع لا تتغير. وCRC يختلف عن توقيع ضد التلاعب المتعمد. في جواب الجودة اربط الآلية بنوع الخطأ، ولا تجمع checksum وBackup وUnit-Test كأنها نفس الحل.</p>'));
})();
